const now = new Date();
const run_id = `SANYO-${now.toISOString().replace(/[-:.TZ]/g,'')}-${Math.random().toString(36).slice(2,8)}`;

return [{
  json: {
    run_id,
    status: 'INTAKE',
    created_at: now.toISOString(),
    brand: 'Sanyo Yusoki Vietnam',
    input: {
      topic: 'REPLACE_TOPIC',
      audience: 'REPLACE_AUDIENCE',
      objective: 'REPLACE_OBJECTIVE',
      platform: 'TikTok'
    }
  }
}];

const d = $json;
const input = d.input || {};

if (!input.topic || input.topic === 'REPLACE_TOPIC') {
  throw new Error('INPUT ERROR: topic chưa được khai báo');
}

return [{ json: {
  ...d,
  status: 'CUSTOMER_INSIGHT',
  customer_insight: {
    problem: input.topic,
    audience: input.audience,
    desired_change: input.objective
  }
}}];

const d = $json;
return [{ json: {
  ...d,
  status: 'CONTENT_GENERATION',
  content: {
    hook: '',
    story: '',
    analysis: '',
    cta: ''
  },
  generation_instruction: `Tạo nội dung thương hiệu Sanyo Yusoki Vietnam dựa trên customer insight. Ưu tiên hữu ích, rõ ràng, đáng tin cậy; không phóng đại; CTA tự nhiên.`
}}];

const d = $json;
return [{ json: {
  ...d,
  status: 'VIDEO_BRIEF',
  video_brief: {
    duration_seconds: 60,
    structure: ['HOOK 0-5s','STORY 5-25s','ANALYSIS 25-50s','CTA 50-60s'],
    visual_direction: 'Japanese premium, trustworthy, family-oriented',
    camera: 'natural cinematic movement',
    audio: 'clear Vietnamese voiceover',
    continuity_required: true
  }
}}];

const d = $json;
return [{ json: {
  ...d,
  status: 'PROMPT_ASSEMBLY',
  prompts: {
    master: '',
    negative: 'distorted architecture, inconsistent elevator dimensions, unreadable text, extra people, duplicated objects, unstable geometry, unrealistic motion',
    continuity: 'same architecture, same elevator design, same family appearance, consistent lighting and spatial relationships'
  }
}}];

const d = $json;
return [{ json: {
  ...d,
  status: 'ASSET_SELECTION',
  assets: {
    brand: true,
    elevator: true,
    cabin: true,
    family: true,
    architecture: true,
    location: true,
    material: true
  }
}}];

const d = $json;
return [{ json: {
  ...d,
  status: 'VEO_PRODUCTION',
  production: {
    engine: 'VEO_3',
    ready_for_generation: true,
    prompt_ready: Boolean(d.prompts),
    asset_ready: Boolean(d.assets)
  }
}}];

const d = $json;
const checks = {
  accuracy: true,
  brand_consistency: true,
  customer_relevance: true,
  clarity: true,
  trustworthiness: true,
  legal_safety: true,
  cta: true,
  continuity: Boolean(d.production?.ready_for_generation)
};

const failed = Object.entries(checks).filter(([,v]) => !v).map(([k]) => k);

return [{ json: {
  ...d,
  status: failed.length ? 'QUALITY_FAIL' : 'QUALITY_PASS',
  quality_gate: {
    checks,
    failed,
    score: Object.values(checks).filter(Boolean).length / Object.keys(checks).length
  }
}}];

const d = $json;
return [{ json: {
  ...d,
  status: 'HUMAN_REVIEW',
  human_review: {
    required: true,
    decision: 'PENDING',
    reviewer: '',
    notes: ''
  }
}}];

const d = $json;
return [{ json: {
  ...d,
  status: 'CALIBRATED',
  calibration: {
    required: true,
    brand_check: 'PASS',
    customer_check: 'PASS',
    visual_check: 'PASS',
    message_check: 'PASS',
    final_adjustment: 'PENDING'
  }
}}];

const d = $json;
const output = {
  run_id: d.run_id,
  status: 'FINAL',
  generated_at: new Date().toISOString(),
  brand: d.brand,
  customer_insight: d.customer_insight,
  content: d.content,
  video_brief: d.video_brief,
  prompts: d.prompts,
  assets: d.assets,
  quality_gate: d.quality_gate,
  calibration: d.calibration,
  production: d.production
};

return [{ json: output }];

const d = $json;
return [{ json: {
  ...d,
  status: 'MEASUREMENT_READY',
  measurement: {
    run_id: d.run_id,
    platform: d.input?.platform || 'unknown',
    metrics_to_collect: ['views','watch_time','completion_rate','engagement_rate','leads','contracts'],
    learning_loop: true
  }
}}];

const d = $json;
return [{ json: {
  ...d,
  status: 'LEARNING_LOOP',
  next_action: 'Store performance data and feed validated insights into the next content generation cycle.'
}}];

const d = $json;
return [{ json: {
  run_id: d.run_id,
  status: 'ERROR_REVIEW_REQUIRED',
  failed_checks: d.quality_gate?.failed || [],
  retry_policy: 'Return to content/prompt stage after correction; never publish failed output.'
}}];
